// Predefined illustrated avatars, served from /static/avatars/<id>.svg.
// Generated by scripts/generate-avatars.js - keep the count in sync with that script.
const AVATAR_COUNT = 12;

const AVATAR_IDS = Array.from(
  { length: AVATAR_COUNT },
  (_, i) => `avatar_${String(i + 1).padStart(2, '0')}`,
);

const avatarPath = (id) => `/static/avatars/${id}.svg`;

module.exports = { AVATAR_IDS, avatarPath };
